from pathlib import Path
import json,sys
expected=['S1_8K_OK','TEST=C005_P11','AP_READY=1','BAD_CROSSED=1','BAD_A=33','BAD_B=44','GOOD_RETRY=1','GOOD_ACCEPT=1','GOOD_A=33','GOOD_B=44','GOOD_VERSION=02','AP_DONE=1','DONE']
trace=Path(sys.argv[1]).read_text(encoding='ascii',errors='replace').splitlines();checks={'trace_exact':trace==expected,'two_cpu_participation':all(x in trace for x in ['AP_READY=1','AP_DONE=1']),'unchecked_snapshot_crosses_write':all(x in trace for x in ['BAD_CROSSED=1','BAD_A=33','BAD_B=44']),'version_validation_retries_then_accepts':all(x in trace for x in ['GOOD_RETRY=1','GOOD_ACCEPT=1','GOOD_A=33','GOOD_B=44','GOOD_VERSION=02'])};out={'format':'C005_P11_EVALUATION_V1','passed':all(checks.values()),'checks':checks,'trace':trace};Path(sys.argv[2]).write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
